import React from 'react';
import {
    UserOutlined,
    NotificationOutlined,
    ContactsOutlined,
    SettingOutlined
} from '@ant-design/icons';
import { Menu } from 'antd';
import '../styles/Sidebar.css'; // Importar estilos del Sidebar

const Sidebar = ({ visible, onClose }) => {
    const items = [
        { key: '1', icon: <UserOutlined />, label: 'Perfil' },
        { key: '2', icon: <NotificationOutlined />, label: 'Notificación' },
        { key: '3', icon: <ContactsOutlined />, label: 'Contacto' },
        { key: '4', icon: <SettingOutlined />, label: 'Configuraciones' }
    ];

    return (
        <div className={`sidebar ${visible ? 'visible' : ''}`}>
            <Menu
                defaultSelectedKeys={['1']}
                mode="inline"
                theme="dark"
                inlineCollapsed={!visible}
                items={items}
            />
        </div>
    );
};

export default Sidebar;
